/*
 * punku-chat forwarder. This file is not the widget, and no build writes it.
 * Older embeds load this jsDelivr path. It loads the v1 release from
 * cdn.punku.ai, the file that current embeds load. If that load fails, it
 * loads widget.min.js, the full widget of the same release, from jsDelivr.
 * See SELF_HOSTING.md in PUNKU-AI/punku-embedded-chat.
 */
(function () {
  if (window.customElements && window.customElements.get("punku-chat")) return;
  var SOURCES = [
    "https://cdn.punku.ai/chat/v1/bundle.min.js",
    "https://cdn.jsdelivr.net/gh/PUNKU-AI/punku-embedded-chat@v1/dist/build/static/js/widget.min.js"
  ];
  function load(i) {
    if (i >= SOURCES.length) return;
    var script = document.createElement("script");
    script.src = SOURCES[i];
    script.async = true;
    script.onerror = function () { load(i + 1); };
    (document.head || document.documentElement).appendChild(script);
  }
  load(0);
})();
